import{_ as o,o as a,c as s,a2 as c}from"./chunks/framework.BM5YPQmL.js";const h=JSON.parse('{"title":"构建 Open Cube OS","description":"","frontmatter":{},"headers":[],"relativePath":"zh/root/BUILDING.md","filePath":"zh/root/BUILDING.md"}'),d={name:"zh/root/BUILDING.md"};function t(n,e,i,l,p,r){return a(),s("div",null,[...e[0]||(e[0]=[c(`<h1 id="构建-open-cube-os" tabindex="-1">构建 Open Cube OS <a class="header-anchor" href="#构建-open-cube-os" aria-label="Permalink to &quot;构建 Open Cube OS&quot;">​</a></h1><p>下文的一切都是可执行的现实：文件名、目标与检查来自 <code>Makefile</code>、<code>tools/build.sh</code>、<code>tools/build.ps1</code> 和 CI 流水线 （<code>.github/workflows/build.yml</code>）。</p><h2 id="你得到什么" tabindex="-1">你得到什么 <a class="header-anchor" href="#你得到什么" aria-label="Permalink to &quot;你得到什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目标</th><th>产出</th></tr></thead><tbody><tr><td><code>make kernel</code></td><td><code>build/opencube.elf</code>——内核 ELF（0 警告，<code>-Wall -Wextra -Werror</code>）</td></tr><tr><td><code>make iso</code></td><td><code>build/opencube.iso</code>——混合 BIOS+UEFI 可启动 ISO</td></tr><tr><td><code>make src-zip</code></td><td><code>dist/OpenCubeOS-&lt;version&gt;-src.zip</code>——确定性源码 zip</td></tr><tr><td><code>make ota</code></td><td><code>dist/OpenCubeOS-&lt;version&gt;-update.tar.gz</code>——OTA 更新包</td></tr><tr><td><code>make all</code></td><td>内核 + ISO + SRC zip + OTA</td></tr><tr><td><code>make test</code></td><td>宿主机侧单元测试（<code>tools/run_host_tests.py</code>）</td></tr><tr><td><code>make reproducible-check</code></td><td>两次干净构建，逐字节相同的 ELF</td></tr><tr><td><code>make api-docs</code></td><td>真实代码树的文档数据（<code>docs/data/*.json</code>）</td></tr></tbody></table><p>一键入口：<code>tools/build.sh</code>（Linux；同样的目标名，外加依赖 检测和 <code>--install</code>）、<code>build.ps1</code>（Windows，经 WSL2 / MSYS2）。</p><h2 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h2><h3 id="依赖" tabindex="-1">依赖 <a class="header-anchor" href="#依赖" aria-label="Permalink to &quot;依赖&quot;">​</a></h3><p><code>gcc, ld (binutils), nasm, grub-mkimage (grub-common), xorriso, mtools (mformat/mcopy), python3, zip</code>。</p><p><code>tools/build.sh</code> 会检查它们并打印缺失项的确切 Debian 包名； 你是 root 时 <code>tools/build.sh --install</code> 用 apt 安装。构建 ISO 还需要 GRUB 模块树（<code>i386-pc</code> 用 <code>grub-pc-bin</code>、 <code>x86_64-efi</code> 用 <code>grub-efi-amd64-bin</code>）和 <code>grub-common</code> 的 <code>unicode.pf2</code>。</p><p>QEMU 测试：<code>qemu-system-x86</code>、<code>seabios</code>、<code>ipxe-qemu</code>、<code>ovmf</code> （UEFI）。在 Debian/Ubuntu 宿主机上：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt-get install gcc nasm xorriso mtools \\</span></span>
<span class="line"><span>     grub-common grub-pc-bin grub-efi-amd64-bin zip python3 \\</span></span>
<span class="line"><span>     qemu-system-x86 ovmf</span></span></code></pre></div><h3 id="构建" tabindex="-1">构建 <a class="header-anchor" href="#构建" aria-label="Permalink to &quot;构建&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git clone https://github.com/cubestudio-dev/OpenCubeOS.git</span></span>
<span class="line"><span>cd OpenCubeOS</span></span>
<span class="line"><span>tools/build.sh        # = make all</span></span>
<span class="line"><span># or step by step:</span></span>
<span class="line"><span>make -j&quot;$(nproc)&quot; kernel</span></span>
<span class="line"><span>make iso</span></span></code></pre></div><p>版本横幅来自 Makefile 中的 <code>2.2.0</code> 字面量（用 <code>make OC_RELEASE_VERSION=1.0.1-test1</code> 覆盖）。构建号是 提交计数加上 +21 对齐偏移（见 Makefile 注记），公开序列因此 保持在已发布的 274 之上。</p><h3 id="启动与测试" tabindex="-1">启动与测试 <a class="header-anchor" href="#启动与测试" aria-label="Permalink to &quot;启动与测试&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make run-bios     # QEMU legacy BIOS boot</span></span>
<span class="line"><span>make run-uefi     # QEMU UEFI boot (OVMF)</span></span>
<span class="line"><span>make test         # host unit tests</span></span>
<span class="line"><span>make shot-bios    # boot screenshot capture</span></span></code></pre></div><p>开启网络：加上 <code>-netdev user,id=n1 -device e1000,netdev=n1</code> （<code>run-bios</code> 目标已经加了），然后在客户机里 <code>dhcp</code>。</p><h3 id="可复现验证" tabindex="-1">可复现验证 <a class="header-anchor" href="#可复现验证" aria-label="Permalink to &quot;可复现验证&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make reproducible-check</span></span>
<span class="line"><span># reproducible-check: PASS - ELF byte-identical across two clean builds</span></span></code></pre></div><p>确定性来源（全部在树内验证）：无 <code>__DATE__</code>/<code>__TIME__</code>/ <code>__TIMESTAMP__</code> 宏、相同输入下稳定的 <code>grub-mkimage</code> 输出、 固定的链接顺序、<code>strip --strip-debug</code> 移除携带路径的节。SRC zip 构造上就是确定性的（<code>git archive</code>：树序、提交 mtime、 索引权限）。OTA 包内嵌构建日（UTC）——它一天之内逐字节 可复现，这是文档声明的保证。</p><p>导出的 <code>SOURCE_DATE_EPOCH</code> 会被遵守并转发给打包 子工具。</p><h3 id="交叉编译-arm64-risc-v-上线-shell" tabindex="-1">交叉编译（ARM64 / RISC-V 上线 shell） <a class="header-anchor" href="#交叉编译-arm64-risc-v-上线-shell" aria-label="Permalink to &quot;交叉编译（ARM64 / RISC-V 上线 shell）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make ARCH=arm64    # build/arch/arm64/opencube-arm64.elf (PL011 UART shell)</span></span>
<span class="line"><span>make ARCH=riscv    # build/arch/riscv/opencube-riscv.elf (NS16550A UART shell)</span></span></code></pre></div><p>这些是真实的裸机上线 shell：带真除数编程的 PL011 / NS16550A UART、ARM 通用定时器 / RISC-V CLINT mtime 计数器，以及 1 秒心跳——横幅与递增的心跳在 QEMU 中实测 验证（<code>qemu-system-aarch64 -M virt</code>、 <code>qemu-system-riscv64 -M virt</code>）。完整内核特性集仅限 x86_64。</p><p>交叉工具链包（Debian）： <code>gcc-aarch64-linux-gnu binutils-aarch64-linux-gnu</code>、 <code>gcc-riscv64-linux-gnu binutils-riscv64-linux-gnu</code>、 <code>qemu-system-arm</code>、<code>qemu-system-misc</code>。</p><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h2><p><code>build.ps1</code>（PowerShell）把构建转发给同一份 Makefile，从 最优的可用环境开始，顺序如下：</p><ol><li><strong>WSL2</strong>（推荐）——带上述 Linux 依赖的 Debian/Ubuntu WSL 发行版。脚本用 <code>wslpath</code> 翻译 Windows 路径并在 WSL 里运行 <code>make</code>。</li><li><strong>MSYS2</strong>——本地安装的 MSYS2，PATH 上有 <code>mingw-w64</code> gcc、nasm、mtools、xorriso、grub 包。</li><li>否则脚本打印需要安装的确切包并以非零 状态退出。</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>powershell -ExecutionPolicy Bypass -File build.ps1            # full pipeline</span></span>
<span class="line"><span>powershell -ExecutionPolicy Bypass -File build.ps1 iso        # kernel + ISO</span></span></code></pre></div><h2 id="多配置构建" tabindex="-1">多配置构建 <a class="header-anchor" href="#多配置构建" aria-label="Permalink to &quot;多配置构建&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make defconfig          # write .config (all options on)</span></span>
<span class="line"><span>make menuconfig         # interactive configurator (tools/oc_menuconfig.sh)</span></span>
<span class="line"><span>make CONFIG_TUI=n       # one-shot override</span></span></code></pre></div><p>选项：<code>CONFIG_TUI</code>、<code>CONFIG_CHINESE</code>、<code>CONFIG_NVME</code>、<code>CONFIG_AHCI</code>、 <code>CONFIG_VIRTIO_BLK</code>。<code>CONFIG_CHINESE=n</code> 强制 <code>CONFIG_TUI=n</code>。 <code>CONFIG_TUI=n CONFIG_CHINESE=n</code> 构建会从 ush 面上摘掉 9 条 TUI 命令，并把 8 条中文 locale SVC 操作变成干净的 -1 错误（命令体住在被过滤的树里；操作号 保持稳定）；完整配置启动 99 条 L0 命令、总共 251 个命令归属 （2.1.0 实测验证：off-path ISO 上横幅 + <code>help -a</code>）。 off-path 是真实代码，不是被删除的代码——配置器生成的 头把禁用的特性映射为 no-op 等价物，L1SVC 分发守护 locale 操作（2.1.0：v2.0.0 树曾链接不出 off-path 镜像——已修复）。</p><h2 id="构建缓存" tabindex="-1">构建缓存 <a class="header-anchor" href="#构建缓存" aria-label="Permalink to &quot;构建缓存&quot;">​</a></h2><p>编译缓存（<code>tools/oc_cc.sh</code>）按内容寻址：键是编译器身份 + 完整参数 + 源文件及每个头依赖的内容哈希。发布树上实测： 冷 46.6 秒 -&gt; 热 14.4 秒（186/186 个对象命中，3.2 倍）， 热输出与冷输出逐字节一致。缓存控制：<code>make cache-stats</code>、 <code>make cache-clear</code>。</p><h2 id="可脚本化的构建-api" tabindex="-1">可脚本化的构建 API <a class="header-anchor" href="#可脚本化的构建-api" aria-label="Permalink to &quot;可脚本化的构建 API&quot;">​</a></h2><p><code>tools/build.sh</code> 把自己的流水线暴露为可 source 的函数 （<code>build_all</code>、<code>build_iso</code>、<code>config_load</code>、<code>cache_lookup</code>、 <code>cross_compile</code>、……），<code>tools/build.sh api-selftest</code> 验证 8 个规格化接口。发布脚本与 CI 组合它们，而不是去解析 make 输出。</p><h2 id="ci" tabindex="-1">CI <a class="header-anchor" href="#ci" aria-label="Permalink to &quot;CI&quot;">​</a></h2><p><code>.github/workflows/build.yml</code> 在每次向 <code>main</code> 的推送和 PR 上 运行：检出（完整历史 + tag，<code>git describe</code> 得以喂给版本 横幅）、依赖安装、内核（<code>-Wall -Wextra -Werror</code>）、混合 ISO、确定性 SRC zip、OTA 包、宿主机测试套件、工件 摘要 + 上传，以及可复现性门禁。QEMU 启动与 E2E 套件是发布宿主机的活动（它们需要持久的 /etc 卷夹具）——完整发布门禁见 <code>docs/release/</code>。</p><h2 id="故障排查" tabindex="-1">故障排查 <a class="header-anchor" href="#故障排查" aria-label="Permalink to &quot;故障排查&quot;">​</a></h2><ul><li><strong><code>grub-mkimage: cannot open ... unicode.pf2</code></strong>——字体在 <code>grub-common</code> 里；若你的发行版拆分了它，把 <code>OC_TOOLS</code> 指向包含 <code>usr/share/grub/unicode.pf2</code> 的目录树。</li><li><strong><code>src-zip: not a git checkout</code></strong>——确定性源码 zip 需要 git 元数据；从克隆构建，或用 <code>make dist</code> 走基于 tar 的普通回退。</li><li><strong>QEMU 找不到固件</strong>——<code>OC_TOOLS</code> 重定位整个 工具链；QEMU 的 datadir 会在 <code>$OC_TOOLS/usr/share/qemu</code> 和 <code>$OC_TOOLS/share/qemu</code> 下探测。</li><li><strong>很新的 GCC/binutils 上的 <code>setc</code> / <code>packed-member</code> 构建 错误</strong>——已在树内修复；更新越过 CI 绿提交 <code>fc4e5a5</code>。</li></ul>`,40)])])}const b=o(d,[["render",t]]);export{h as __pageData,b as default};
